sequence.script:
var v = mc.getProperty("maskInput");
        var out = "";
        if (v !== null && v !== undefined) {
            v = String(v);
            if (v.length <= 5) {
                out = new Array(v.length + 1).join("*");
            } else {
                out = v.substring(0, 3) + new Array(v.length - 4).join("*") + v.substring(v.length - 2);
            }
        }
        mc.setProperty("maskedValue", out);
